var evaluator = new StencilEvaluator();

// bare identifiers read props; size.w / size.h / repeat.index are built in
var label = evaluator.Evaluate("label", context).AsString();
var half  = evaluator.Evaluate("size.w / 2", context).AsDouble();
var fill  = evaluator.Evaluate("token('color.primary', '#000')", context).AsString();

// nothing throws — a malformed expression is simply null
var broken = evaluator.Evaluate("alert(1)", context);   // StencilValue.Null
